import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { walletCheckHandler } from "../handlers/walletCheckHandler";
import type { ApiError } from "../runtime/client";
import type { WalletCheckRequest } from "../types/WalletCheckRequest";

type Data = Awaited<ReturnType<typeof walletCheckHandler>>;
type Vars = WalletCheckRequest;

export function useWalletCheck(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => walletCheckHandler(vars),
    ...options,
  });
}
